@st.cache_data(show_spinner=False)
def img_src(img_id, stroke="#2F2633"):
    for ext, mime in ((".jpg", "image/jpeg"), (".jpeg", "image/jpeg"), (".png", "image/png"), (".webp", "image/webp")):
        f = ASSETS / f"{img_id}{ext}"
        if f.exists():
            return f"data:{mime};base64,{base64.b64encode(f.read_bytes()).decode()}", True

    svg = (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120" fill="none" '
        'stroke="%s" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">%s</svg>'
        % (stroke, _SVG[img_id].replace("@@", stroke))
    )
    return f"data:image/svg+xml;base64,{base64.b64encode(svg.encode()).decode()}", False

LOGO_B64 = ""

ICON_ONLY_B64 = ""

@st.cache_data(show_spinner=False)
def tinted_logo(color):
    try:
        import io
        from PIL import Image
        im = Image.open(io.BytesIO(base64.b64decode(ICON_ONLY_B64))).convert("RGBA")
        rgb = tuple(int(color[i:i + 2], 16) for i in (1, 3, 5))
        out = Image.new("RGBA", im.size, rgb + (255,))
        out.putalpha(im.getchannel("A"))
        buf = io.BytesIO()
        out.save(buf, format="PNG")
        return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode()
    except Exception:
        return None

LOGO_DARK_PURPLE = "#3D2352"

def logo_src(color=None):
    # Keep the Mashina logo a single dark-purple brand color across every view.
    t = tinted_logo(LOGO_DARK_PURPLE)
    if t:
        return t
    return f"data:image/png;base64,{ICON_ONLY_B64}"

AR_DIGITS = str.maketrans("0123456789", "٠١٢٣٤٥٦٧٨٩")
DAYS = ["الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد"]
MONTHS = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"]

OPEN_MIN, CLOSE_MIN = 8 * 60, 24 * 60
SLOTS = list(range(OPEN_MIN, CLOSE_MIN + 1, 30))

def ar(n):
    return str(n).translate(AR_DIGITS)

def ar_date():
    d = datetime.now()
    return f"{DAYS[d.weekday()]}، {ar(d.day)} {MONTHS[d.month - 1]}"

def fmt_min(m):
    # Relative starts may cross midnight; keep the displayed clock accurate.
    minutes = int(m)
    if minutes == 24 * 60:
        return "١٢:٠٠ منتصف الليل"
    h, mi = divmod(minutes % (24 * 60), 60)
    h12 = h % 12 or 12
    return f"{ar(h12)}:{ar(f'{mi:02d}')} {'صباحاً' if h < 12 else 'مساءً'}"

def fmt_clock(sec):
    h, rest = divmod(int(sec), 3600)
    m, s = divmod(rest, 60)
    return ar(f"{h}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}")











