def bar_html(clock, ended=False, frac=1.0):
    label = "انتهى وقت الانتظار" if ended else "ينتهي الانتظار بعد"
    return (
        f"<div class='cd-bar'><span class='cd-label'><i class='pulse'></i>{label}</span>"
        f"<b class='cd-clock'>{clock}</b>"
        f"<div class='cd-prog'><i style='width:{max(0, min(frac, 1)) * 100:.1f}%'></i></div></div>"
    )

def live_bar_html(p):
    sec = remaining(p)
    return bar_html(fmt_clock(sec), ended=(sec == 0), frac=sec / max(p["starts_in_min"] * 60, 1))

def banner_html(p):
    cat = p["category"]
    img = IMG_BY_ID.get(p.get("image") or "")
    if not img and cat in IMAGES:
        img = IMAGES[cat][0]
    if not img:
        return f"<div class='banner'><div class='hint'>{'اختر صورة' if cat in IMAGES else 'اختر الفئة'}</div></div>"

    src, photo = img_src(img["id"], theme(cat)["deep"])
    if photo:
        return f"<div class='banner' style='background-image:url({src});background-size:cover'></div>"
    return f"<div class='banner illus' style='background-image:url({src})'></div>"

def participant_entries(p):
    raw_attendees = list(p.get("_attendee_identities", p.get("attendees", [])))
    display_attendees = list(p.get("attendees", []))
    raw_host = p.get("_host_identity", p.get("host", ""))
    owner = {"name": p.get("host", "").strip(), "identity": raw_host}
    others = []
    skipped_host = False
    for idx, raw in enumerate(raw_attendees):
        display = (display_attendees[idx] if idx < len(display_attendees) else participant_display(raw)).strip()
        if not skipped_host and str(raw).lower() == str(raw_host).lower():
            skipped_host = True
            continue
        if display:
            others.append({"name": display, "identity": raw})
    return owner, others


def plan_participants(p):
    owner, others = participant_entries(p)
    return owner["name"], [person["name"] for person in others]

def people_html(p, mine=False):
    owner_entry, other_entries = participant_entries(p)
    owner = owner_entry["name"]
    others = [person["name"] for person in other_entries]
    everyone = [owner, *others]
    c = theme(p["category"])
    avs = "".join(
        f"<div class='av' style='background:{c['bg']};color:{c['deep']}'>"
        f"{esc(person[:2].upper())}</div>" for person in everyone[:3]
    )
    owner_tag = (
        f"<b>{esc(owner)}</b><span style='display:inline-block;margin:0 6px;padding:1px 9px;"
        f"border-radius:999px;background:{c['bg']};color:{c['deep']};font-size:11px;"
        f"font-weight:800;line-height:1.6;vertical-align:middle'>صاحب الخطة</span>"
    )
    names = "، ".join([owner_tag, *(esc(person) for person in others)])
    return (
        f"<div class='people'><div class='stack'>{avs}</div>{ar(len(everyone))} منضم</div>"
        f"<p class='names'>{names}</p>"
    )

def when_text(p):
    s, e = p["start"], p["end"]
    if s is not None and e is not None:
        return f"{fmt_min(s)} – {fmt_min(e)}"
    if s is not None:
        return f"{fmt_min(s)} – وقت النهاية"
    return "وقت البداية – وقت النهاية"

def body_html(p, mine=False, show_people=True):
    badge = ""
    cat_name = CAT_NAMES.get(p["category"], "الفئة")
    return (
        banner_html(p)
        + "<div class='body'><div class='pills'>"
        + f"<span class='catpill' style='background:{theme(p['category'])['bg']}'><i></i>{cat_name}</span>{badge}</div>"
        + f"<h3>{esc(p['title'])}</h3>"
        + f"<p class='by'>بواسطة <b>{esc(p['host'])}</b></p>"
        + (f"<p class='description'>{esc(p.get('description',''))}</p>" if p.get('description') else "<p class='description'></p>")
        + f"<p class='meta'><span class='ic'>{PIN}</span>{esc(p['place'])}</p>"
        + f"<p class='meta'><span class='ic'>{CLOCK}</span>{when_text(p)}</p>"
        + (people_html(p, mine=mine) if show_people else "")
        + "</div>"
    )

def ticket_html(p, name, owner_view=False):
    c = theme(p["category"])
    waiting_owner = owner_view and remaining(p) > 0

    if waiting_owner:
        title = "خطتك قيد الإنشاء"
        subtitle = "وقت الانتظار ما انتهى، تقدر تتابع المنضمين هنا"
        hero_icon = f"<div class='tk-wait-icon' aria-hidden='true'>{HOURGLASS}</div>"
    else:
        colors = [c["deep"], "#FFFFFF", "#AE83C8", "#B96E9B", c["deep"], "#A982C0"]
        confetti = "".join(
            f"<i style='right:{5 + i * 8}%;background:{colors[i % len(colors)]};animation-delay:{(i % 5) * .12:.2f}s'></i>"
            for i in range(12)
        )
        hero_icon = (
            f"<div class='confetti'>{confetti}</div>"
            "<svg class='tk-check' viewBox='0 0 80 80'>"
            "<circle cx='40' cy='40' r='38'/><path d='M24 41l11 11 21-23'/></svg>"
        )
        if owner_view:
            title, subtitle = "انتهى وقت الانتظار!", "هذي تفاصيل خطتك وكل المنضمين"
        else:
            title, subtitle = "تم انضمامك!", "مقعدك محجوز، لا تتأخر علينا"

    return (
        f"<div class='tk-hero' style='background:{c['bg']}'>"
        f"{hero_icon}"
        f"<div class='tk-t'>{title}</div>"
        f"<div class='tk-s'>{subtitle}</div></div>"
        "<div class='perf'><span></span></div>"
        "<div class='tk-body'>"
        f"<div class='tk-who'><b>{esc(p['title'])}</b></div>"
        f"<p class='meta'><span class='ic'>{PIN}</span>{esc(p['place'])}</p>"
        f"<p class='meta'><span class='ic'>{CLOCK}</span>{when_text(p)}</p>"
        f"<p class='meta'><span class='ic'>{USERS}</span>بواسطة {esc(p['host'])}</p></div>"
    )

def owner_ticket_html(p):
    return ticket_html(p, p["host"], owner_view=True)

@st.fragment(run_every=1)
def countdown(pid):
    p = get_plan(pid)
    if p:
        st.markdown(live_bar_html(p), unsafe_allow_html=True)

