def empty_state(filtering, query="", category="All"):
    with st.container(key="empty_state"):
        if filtering:
            query = (query or "").strip()
            what = f"“{esc(query)}”" if query else "الفلتر اللي اخترته"
            scope = f" في {CAT_NAMES.get(category, category)}" if query and category != "All" else ""
            title = "ما لقينا خطة تناسب بحثك"
            text = f"ما فيه نتائج لـ {what}{scope}. جرّب كلمة بحث ثانية."
        else:
            title = "ما فيه خطط للحين"
            text = "حالياً ما فيه خطط متاحة. أنشئ أول خطة وخَل غيرك ينضم لك."

        st.markdown(
            f"<div class='empty'><div class='empty-icon'><span>⌕</span></div>"
            f"<h3>{title}</h3><p>{text}</p></div>",
            unsafe_allow_html=True,
        )

        if filtering:
            _, a, b, _ = st.columns([1.0, 1.35, 1.35, 1.0], gap="small")
            with a:
                if st.button("أنشئ خطة", key="empty_create", on_click=go, args=("Create",), use_container_width=True):
                    st.rerun(scope="app")  # زر داخل fragment: افتح صفحة الإنشاء بالتحديث الكامل
            with b:
                if st.button("الخطط المتاحة", key="empty_clear", on_click=show_all_plans, use_container_width=True):
                    st.rerun(scope="app")  # مرة واحدة إلى قائمة الخطط بدون إعادة تطبيق الفلتر القديم
        else:
            _, mid, _ = st.columns([1.7, 1.8, 1.7])
            with mid:
                if st.button("أنشئ خطة", key="empty_create", on_click=go, args=("Create",), use_container_width=True):
                    st.rerun(scope="app")

