def dialog_center_css(key):
    """Compact popup: hugs its content, X stays top-right, buttons keep fixed spots."""
    d = f'div[data-testid="stDialog"] [role="dialog"]:has(.st-key-{key})'
    k = f".st-key-{key}"
    return f"""
      div[data-testid="stDialog"] div:has({k}),
      div[data-baseweb="modal"] div:has({k}),
      [role="dialog"]:has({k}) {{
        background:transparent !important;
        background-color:transparent !important;
        box-shadow:none !important;
        border:none !important;
        outline:none !important;
        backdrop-filter:none !important;
        filter:none !important;
      }}
      div[data-testid="stDialog"] [role="dialog"]:not(:has({k})),
      div[data-baseweb="modal"] [role="dialog"]:not(:has({k})) {{
        background:transparent !important;
        box-shadow:none !important;
        border:none !important;
      }}
      {d} {{
        background:#FFFFFF !important;
        border:1px solid #E3D8EB !important;
        border-radius:27px !important;
        box-shadow:0 22px 75px rgba(91,61,117,.18) !important;
      }}
      div[data-testid="stDialog"] div:has({k})::before,
      div[data-testid="stDialog"] div:has({k})::after {{display:none !important;}}
      {d} {{
        position:relative !important;
        height:auto !important;
        min-height:0 !important;
        width:min(400px, 92vw) !important;
        max-width:400px !important;
        padding:46px 24px 24px !important;
      }}
      {d} [data-testid="stDialogHeader"] {{
        position:static !important;
        height:0 !important;
        min-height:0 !important;
        margin:0 !important;
        padding:0 !important;
        overflow:visible !important;
        background:transparent !important;
      }}
      {d} [data-testid="stDialogHeader"] button,
      {d} button[aria-label="Close"] {{
        position:absolute !important;
        top:12px !important;
        right:14px !important;
        left:auto !important;
        inset-inline:auto !important;
        margin:0 !important;
        z-index:5 !important;
      }}
      {d} [data-testid="stVerticalBlock"] {{gap:14px !important;}}
      {d} [data-testid="stElementContainer"]:has(style) {{display:none !important;}}
      {d} [data-testid="stHorizontalBlock"] {{
        display:grid !important;
        grid-template-columns:1fr 1fr !important;
        direction:ltr !important;
        align-items:center !important;
        gap:14px !important;
        width:100% !important;
        flex-wrap:nowrap !important;
      }}
      {d} [data-testid="stColumn"] {{
        width:100% !important;
        min-width:0 !important;
        flex:none !important;
      }}
      {d} [data-testid="stColumn"] [data-testid="stVerticalBlock"],
      {d} [data-testid="stColumn"] [data-testid="stElementContainer"],
      {d} [data-testid="stColumn"] [data-testid="stButton"] {{
        width:100% !important;
        margin:0 !important;
        padding:0 !important;
      }}
      {d} [data-testid="stColumn"] button {{
        width:100% !important;
        height:50px !important;
        min-height:50px !important;
        margin:0 !important;
        padding:0 12px !important;
        display:flex !important;
        align-items:center !important;
        justify-content:center !important;
      }}
    """

