@st.fragment(run_every=1)
def render_home_board(query="", category="All"):
    # If a joined participant is browsing the board and the host cancels that plan,
    # force one full rerun so app.py can show the cancellation popup immediately.
    tracked_plan_id = S.get("my_plan_id")
    if S.get("joined") and tracked_plan_id is not None and get_plan(tracked_plan_id) is None:
        st.rerun(scope="app")
        return
    if S.owner_expiry_pending is None and any(
           p["owner"] == S.uid and remaining(p) == 0
           and p["id"] not in S.owner_expiry_notified
           for p in store()["plans"]):
        st.rerun(scope="app")
    prune_expired_plans()
    newly_hidden = {p["id"] for p in store()["plans"]
                    if p["owner"] == S.uid and p["id"] in S.owner_expiry_notified
                    and not show_public_card(p)} - S.home_removed_after_grace
    if newly_hidden:
        S.home_removed_after_grace = set(S.home_removed_after_grace) | newly_hidden
        st.rerun(scope="app")
    query = (query or "").strip()
    category = category if category in CATS or category == "All" else "All"
    plans = (search_plans(query, include_grace=True)
             if query else get_active_plans(include_grace=True))
    if category != "All":
        plans = [p for p in plans if p["category"] == category]

    if not plans:
        st.markdown("<div style='height:22px'></div>", unsafe_allow_html=True)
        empty_state(bool(query) or category != "All", query, category)
        return

    mine = [] if query else [p for p in plans if p["owner"] == S.uid]
    others = [p for p in plans if p["owner"] != S.uid]

    current_name = S.get("name", "").strip()
    membership = get_active_membership(current_name)
    active_plan_id = membership["id"] if membership else None

    # When the user returns to the board while still joined, keep that plan in
    # its own section at the very top. All remaining cards stay visible below,
    # but render_card keeps their join action locked until the membership ends.
    joined_plan = None
    if active_plan_id is not None:
        joined_plan = next((p for p in others if p["id"] == active_plan_id), None)
        if joined_plan is None:
            joined_plan = next((p for p in others if current_name and has_joined(p, current_name)), None)

    remaining_others = [p for p in others if joined_plan is None or p["id"] != joined_plan["id"]]

    if joined_plan is not None:
        st.markdown("<p class='section-label'>الخطة الي منضم اليها <span>١</span></p>", unsafe_allow_html=True)
        render_grid([joined_plan], active_plan_id=active_plan_id)

    if mine:
        st.markdown(f"<p class='section-label'>خططي <span>{ar(len(mine))}</span></p>", unsafe_allow_html=True)
        render_grid(mine, active_plan_id=active_plan_id)

    section_title = "باقي الخطط" if joined_plan is not None else "الخطط المتاحة"
    st.markdown(f"<p class='section-label'>{section_title} <span>{ar(len(remaining_others))}</span></p>", unsafe_allow_html=True)
    if remaining_others:
        render_grid(remaining_others, active_plan_id=active_plan_id)
    elif mine or joined_plan is not None:
        st.markdown("<p class='section-note no-plans-note'>ما فيه خطط ثانية متاحة حالياً.</p>", unsafe_allow_html=True)

