@st.fragment(run_every=1)
def participants_panel(pid, name, owner_view=False):
    p = get_plan(pid)

    if p is None or (not owner_view and not has_joined(p, name)):
        if p is None:
            S.pop("toast_msg", None)
        else:
            S.toast_msg = "طلعت من الخطة"
        S.joined = None
        st.rerun()
        return

    owner_entry, other_entries = participant_entries(p)
    owner = owner_entry["name"]
    current_identity = participant_identity(name)
    c = theme(p["category"])
    owner_is_me = str(owner_entry["identity"]).lower() == str(current_identity).lower()
    rows = (
        f"<div class='person'><span class='pav {p['category']}' style='background:{c['bg']};color:{c['deep']}'>{esc(owner[:1].upper())}</span>"
        f"<span class='pn'>{esc(owner)} <span style='display:inline-block;margin-right:7px;padding:3px 9px;border-radius:999px;background:{c['deep']};color:#fff;font-size:12px;font-weight:800;vertical-align:middle'>صاحب الخطة</span></span>"
        + ("<span class='role soft'>أنت</span>" if owner_is_me else "")
        + "</div>"
    )
    for person in other_entries:
        person_name = person["name"]
        person_is_me = str(person["identity"]).lower() == str(current_identity).lower()
        rows += (
            f"<div class='person'><span class='pav {p['category']}'>{esc(person_name[:1].upper())}</span>"
            f"<span class='pn'>{esc(person_name)}</span>"
            + ("<span class='role soft'>أنت</span>" if person_is_me else "")
            + "</div>"
        )

    n = 1 + len(other_entries)
    with st.container(key=f"people_panel_{p['category']}"):
        st.markdown(
            f"<div dir='rtl' style='direction:rtl;text-align:right;width:100%'><p class='panel-h'>مين موجود</p>{rows}</div>",
            unsafe_allow_html=True,
        )

