def plan_end_countdown_html(p):
    secs = plan_seconds_left(p)
    initial = max(int((plan_end_at(p) - wait_end_at(p)).total_seconds()), 1)
    if secs > 0:
        return bar_html(fmt_clock(secs), frac=secs / initial).replace(
            "ينتهي الانتظار بعد", "تنتهي الخطة بعد"
        )
    return bar_html(fmt_clock(0), ended=True, frac=0).replace(
        "انتهى وقت الانتظار", "انتهى وقت الخطة"
    )

@st.fragment(run_every=1)
def owner_plan_countdown(pid):
    p = get_plan(pid)
    if p is None:
        return
    if remaining(p) == 0 and pid not in S.owner_expiry_notified:
        st.rerun(scope="app")
        return
    if remaining(p) > 0:
        st.markdown(live_bar_html(p), unsafe_allow_html=True)
    else:
        st.markdown(plan_end_countdown_html(p), unsafe_allow_html=True)

@st.fragment(run_every=1)
def viewer_plan_countdown(pid):
    p = get_plan(pid)
    if p is None:
        return
    if remaining(p) > 0:
        st.markdown(live_bar_html(p), unsafe_allow_html=True)
    else:
        st.markdown(plan_end_countdown_html(p), unsafe_allow_html=True)

